/bin/bash -lc "node --input-type=module - <<'NODE'
import { execFileSync } from 'node:child_process';
const exe = '/workspace/dataset/test13_executable';
const scenarios = [
  ['unknown', ['--c', '1']],
  ['duplicate a', ['--a', '1', '--a', '2', '--b', '{}']],
  ['b before a', ['--b', '{}', '--a', '1']],
  ['equals form', ['--a=1', '--b={}']],
  ['double dash then args', ['--', '--a', '1', '--b', '{}']],
  ['short h', ['-h']],
  ['short a missing opt', ['-a', '1', '--b', '{}']],
  ['missing a value', ['--a', '--b', '{}']],
  ['positional extra', ['--a', '1', '--b', '{}', 'x']],
  ['option value looks like option', ['--a', '--x', '--b', '{}']],
];
for (const [name, args] of scenarios) {
  try {
    const out = execFileSync(exe, args, { encoding:'utf8', stderr:'pipe' });
    console.log(name + ' => OK ' + JSON.stringify(out.trim().split(/\\n/)));
  } catch (err) {
    const code = err.status;
    const merged = String(err.stdout || '') + String(err.stderr || '');
    console.log(name + ' => EXIT ' + code + ' ' + JSON.stringify(merged.trim().split(/\\n/)));
  }
}
NODE"

