import { spawnSync } from 'node:child_process';
const exe = '/workspace/dataset/test13_executable';
const nodeScript = '/output/test13.mjs';
const cases = [
  [],
  ['--help'],
  ['--a', '{}'],
  ['--a', '{}', '--b', '{}'],
  ['--a=--x', '--b', '{}'],
  ['--a', '-1', '--b', '{}'],
  ['--a', '-1e3', '--b', '{}'],
  ['--a', '{\"a\":1,\"b\":2}', '--b', '{\"type\":\"object\",\"properties\":{\"a\":{\"type\":\"string\"}},\"additionalProperties\":false}'],
  ['--a', '1', '--b', '{\""'$schema":"http://json-schema.org/draft-07/schema#","type":"string"}'"'],
  ['--a', '1', '--b', '{\""'$schema":"https://example.com/unknown","type":"string"}'"'],
  ['--a', '[1,2]', '--b', '{\"items\":{\"type\":\"string\"}}'],
  ['--a', '1', '--b', 'false'],
  ['--a', '--x', '--b', '{}'],
  ['--a', '1', '--b', '{}', 'x'],
  ['--a', '1', '--b', '{}', '--c', '1'],
  ['--', '--a', '1', '--b', '{}'],
  ['--a', '1', '--a', '\"x\"', '--b', '{\"type\":\"string\"}'],
  ['--a', '1', '--b', '{\"type\":\"number\"}', '--b', '{\"type\":\"string\"}'],
];
let mismatches = 0;
for (const args of cases) {
  const left = spawnSync(exe, args, { encoding: 'utf8' });
  const right = spawnSync('node', [nodeScript, ...args], { encoding: 'utf8' });
  const leftText = "'`${left.stdout}${left.stderr}`;
  const rightText = `${right.stdout}${right.stderr}`;
  const same = left.status === right.status && leftText === rightText;
  if (!same) {
    mismatches += 1;
    console.log('"'MISMATCH', JSON.stringify(args));
    console.log('exe status', left.status, 'node status', right.status);
    console.log('exe output:\\n' + leftText);
    console.log('node output:\\n' + rightText);
  }
}
console.log('mismatches=' + mismatches);
NODE"

